with valid as (select id, category, brand, price, cost, stock_qty, launch_date, supplier_id, price + stock_qty as price_plus_stock_qty, coalesce(brand, 'DIRECT') as brand_clean from products where launch_date > date '2023-04-28' and year(launch_date) >= 2025) select * from (select brand, supplier_id, category, price_plus_stock_qty from valid) src pivot (max(price_plus_stock_qty) as total, count(1) as n for category in ('Books' as books, 'Electronics' as electronics));
